describe('Accessible Product Images and Login Fields', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
  });

  it('should have accessible attributes on login fields and product images', () => {
    // Verify login fields have non-empty placeholder attributes
    cy.get('[data-testid="username"]').should('have.attr', 'placeholder', 'Username');
    cy.get('[data-testid="password"]').should('have.attr', 'placeholder', 'Password');

    // Verify login fields are visible and focusable
    cy.get('[data-testid="username"]').should('be.visible');
    cy.get('[data-testid="password"]').should('be.visible');
    cy.get('[data-testid="username"]').click();
    cy.get('[data-testid="password"]').click();

    // Verify login form is submitted with correct credentials
    cy.get('[data-testid="login-button"]').click();
    cy.intercept('POST', '/api/auth/login').as('loginRequest');
    cy.wait('@loginRequest');

    // Verify successful login redirects to dashboard
    cy.url().should('include', '/dashboard');

    // Verify product images have non-empty alt attributes
    cy.get('[data-testid="inventory-item"]').each(($item) => {
      cy.wrap($item).should('have.attr', 'alt');
    });

    // Verify at least one product image has a descriptive alt attribute
    cy.get('[data-testid="inventory-item"]').first().should('have.attr', 'alt', 'Product description');
  });

  it('should handle edge case: missing alt attributes on product images', () => {
    // Navigate to product page
    cy.visit('/product/1');

    // Verify product image has missing alt attribute
    cy.get('[data-testid="inventory-item"]').first().should('have.attr', 'alt', '');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Missing alt attribute');

    // Verify error message is accessible
    cy.get('[data-testid="error-message"]').should('have.attr', 'aria-live', 'polite');

    // Verify user can correct the issue
    cy.get('[data-testid="inventory-item"]').first().click();
    cy.get('[data-testid="alt-field"]').type('Product description');
    cy.get('[data-testid="alt-field"]').type('{enter}');

    // Verify error message disappears
    cy.get('[data-testid="error-message"]').should('not.exist');

    // Verify product image now has a non-empty alt attribute
    cy.get('[data-testid="inventory-item"]').first().should('have.attr', 'alt', 'Product description');
  });
});
